dictionary-encoding.pseudocode:
def dict_encode(column):
    values = sorted(set(column))  # 정렬 사전: 범위 검색 가능
    code = {v: i for i, v in enumerate(values)}
    ids = [code[v] for v in column]  # 값 → 정수 ID
    bits = max(1, (len(values) - 1).bit_length())
    return values, ids, bits  # bits: 비트 패킹 폭

def scan_eq(values, ids, target):
    if target not in values:
        return []
    t = values.index(target)  # 사전에서 한 번만 조회
    # 이후는 문자열 대신 정수 비교
    return [i for i, x in enumerate(ids) if x == t]

differencing.pseudocode:
def diff(y, lag=1):
    # lag=1: 1차 차분, lag=s: 계절 차분
    return [y[t] - y[t - lag] for t in range(lag, len(y))]

def choose_d(y, is_stationary, max_d=2):
    d = 0
    while not is_stationary(y) and d < max_d:
        y = diff(y)  # 추세 제거
        d += 1
    return d, y  # ARIMA(p, d, q)의 d

def undiff(last, dy):
    # 차분 예측값을 원 단위로 복원 (1차 역차분)
    out = []
    for v in dy:
        last = last + v
        out.append(last)
    return out

differential-privacy.pseudocode:
def laplace_mechanism(data, query, sensitivity, eps):
    true_val = query(data)
    scale = sensitivity / eps  # b = Δf / ε
    return true_val + laplace_noise(0, scale)

class PrivacyBudget:
    def __init__(self, total_eps):
        self.remaining = total_eps

    def answer(self, data, query, sensitivity, eps):
        if eps > self.remaining:  # 순차 합성: ε 누적
            raise BudgetExhausted()
        self.remaining -= eps
        return laplace_mechanism(data, query,
                                 sensitivity, eps)

direct-preference-optimization.pseudocode:
def dpo_loss(pi, ref, x, yw, yl, beta=0.1):
    # 암묵적 보상 = beta * log(pi / ref)
    rw = beta * (pi.logp(yw, x) - ref.logp(yw, x))
    rl = beta * (pi.logp(yl, x) - ref.logp(yl, x))
    # 선택(yw)이 거부(yl)보다 선호될 확률 최대화
    return -log_sigmoid(rw - rl)

def train(pi, ref, dataset, lr):
    for x, yw, yl in dataset:
        loss = dpo_loss(pi, ref, x, yw, yl)
        grads = grad(loss, pi.params)
        pi.params -= lr * grads  # ref는 갱신하지 않음
    return pi

direct-sequence-spread-spectrum.pseudocode:
def spread(bits, pn):  # bits, pn: +1/-1 값
    chips = []
    for b in bits:
        for c in pn:
            chips.append(b * c)  # 비트당 len(pn)칩
    return chips

def despread(chips, pn):
    n, out = len(pn), []
    for i in range(0, len(chips), n):
        # 동일 PN과 상관(곱의 합)으로 비트 판정
        corr = sum(chips[i + k] * pn[k] for k in range(n))
        out.append(1 if corr > 0 else -1)
    return out

directed-acyclic-graph.pseudocode:
def topo_sort(graph):
    # graph: {정점: [후속 정점]}, 모든 정점이 키로 존재
    indeg = {v: 0 for v in graph}
    for v in graph:
        for w in graph[v]:
            indeg[w] += 1
    queue = [v for v in graph if indeg[v] == 0]
    order = []
    while queue:
        v = queue.pop(0)  # 진입 차수 0 = 선행 작업 없음
        order.append(v)
        for w in graph[v]:
            indeg[w] -= 1
            if indeg[w] == 0:
                queue.append(w)
    if len(order) < len(graph):
        return None  # 순환 존재 → DAG 아님
    return order

