discrete-cosine-transform.pseudocode:
def dct2(block):  # N×N 블록 (JPEG는 N=8)
    N = len(block)
    out = [[0.0] * N for _ in range(N)]
    for u in range(N):
        for v in range(N):
            cu = sqrt(0.5) if u == 0 else 1.0
            cv = sqrt(0.5) if v == 0 else 1.0
            s = 0.0
            for x in range(N):
                for y in range(N):
                    cx = cos((2 * x + 1) * u * pi / (2 * N))
                    cy = cos((2 * y + 1) * v * pi / (2 * N))
                    s += block[x][y] * cx * cy
            out[u][v] = (2 / N) * cu * cv * s  # N=8이면 1/4
    return out  # out[0][0]=DC, 나머지 AC(우하단일수록 고주파)

distributed-hash-table.pseudocode:
def between(x, a, b):  # 원형 구간 (a, b]
    if a < b:
        return a < x <= b
    return x > a or x <= b

def find_successor(n, key):  # Chord 탐색 O(log N)
    while not between(key, n.id, n.succ.id):
        n = closest_preceding(n, key)
    return n.succ  # 키 담당 노드

def closest_preceding(n, key):
    for f in reversed(n.finger):  # 먼 핑거부터
        # f가 원형 구간 (n, key) 안이면 점프
        if f.id != key and between(f.id, n.id, key):
            return f
    return n.succ
